const cmds = [
 ["session_mentions", "for kind in 'issue 3' 'issue 8' 'issue 9' 'issue 10' 'issue 11' 'issue 12' 'issue 13' 'issue 17' 'pr 14' 'pr 15' 'pr 16' 'pr 18'; do set -- $kind; gh \"$1\" view \"$2\" --repo RGCsAGupta/driftlens --json body,comments --jq '[.body, (.comments[]?.body)] | .[] | select(test(\"session|Session|019f\"))' ; done", 60000],
 ["env", "if test -n \"${OPENAI_API_KEY:-}\"; then printf '[REDACTED: CREDENTIAL]'; else printf '[REDACTED: CREDENTIAL]'; fi\nif test -n \"${OPENAI_MODEL:-}\"; then printf 'OPENAI_MODEL=present\\n'; else printf 'OPENAI_MODEL=absent\\n'; fi", 1000],
 ["treesessions", "gh api 'repos/RGCsAGupta/driftlens/git/trees/main?recursive=1' --jq '[.tree[].path | select(startswith(\"docs/ai-interactions/\"))]'", 5000],
 ["top_sessions_size", "for f in [REDACTED: LOCAL PATH] do test -f \"$f\" || continue; meta=$(head -n1 \"$f\"); cwd=$(printf '%s\\n' \"$meta\"|jq -r '.payload.cwd//\"\"'); case \"$cwd\" in *driftlens*) ;; *) continue;; esac; st=$(printf '%s\\n' \"$meta\"|jq -r '.payload.source|type'); if test \"$st\" = string; then printf '%s\\t%s\\t%s\\n' \"$(printf '%s\\n' \"$meta\"|jq -r '.payload.id')\" \"$(wc -l < \"$f\")\" \"$cwd\"; fi; done", 10000]
];
const results=await Promise.all(cmds.map(async ([name,cmd,cap])=>[name,await tools.exec_command({cmd,workdir:"[REDACTED: LOCAL PATH]",yield_time_ms:30000,max_output_tokens:cap})]));
